'use client';

import { DefaultApiRegistry, type Provider, ProviderSchema } from '@wener/ai/schema';
import type { ComponentPropsWithRef, ReactNode } from 'react';
import {
	AiConfigEditor,
	type AiConfigEditorOption,
	type AiConfigEditorSlots,
	AiConfigFieldGrid,
	AiConfigFieldSlot,
	AiConfigFormSection,
	AiConfigKeyValueField,
	type AiConfigSchema,
	AiConfigSecretField,
	AiConfigSelectField,
	AiConfigStringListField,
	AiConfigTextareaField,
	AiConfigTextField,
	AiConfigToggleField,
	type AiConfigValidationMode,
	type AiResourceEditorMessageOverrides,
	type AiResourceEditorMessages,
	aiConfigFieldError,
	JsonValueEditor,
	mergeResourceEditorMessages,
	useAiConfigDraft,
} from '../../ui/ai-config-editor';

export type AiProviderEditorField =
	| 'id'
	| 'name'
	| 'title'
	| 'description'
	| 'type'
	| 'apiType'
	| 'baseUrl'
	| 'apiKey'
	| 'headers'
	| 'env'
	| 'envVars'
	| 'credentials'
	| 'proxyMode'
	| 'proxy'
	| 'endpoints'
	| 'defaultEndpointId'
	| 'defaultModelId'
	| 'capabilities'
	| 'tags'
	| 'labels'
	| 'notes'
	| 'options'
	| 'extensions'
	| 'enabled';
export type AiProviderEditorSection = 'identity' | 'connection' | 'routing' | 'metadata';
export type AiProviderEditorMessages = AiResourceEditorMessages<AiProviderEditorField, AiProviderEditorSection>;
export type AiProviderEditorMessageOverrides = AiResourceEditorMessageOverrides<
	AiProviderEditorField,
	AiProviderEditorSection
>;

export type AiProviderEditorProps = Omit<ComponentPropsWithRef<'div'>, 'onChange' | 'title'> & {
	value: Provider;
	onChange: (value: Provider) => void;
	onSubmit?: (value: Provider) => void;
	schema?: AiConfigSchema<Provider>;
	validationMode?: AiConfigValidationMode;
	disabled?: boolean;
	readOnly?: boolean;
	messages?: AiProviderEditorMessageOverrides;
	slots?: AiConfigEditorSlots<Provider>;
	apiTypeOptions?: readonly AiConfigEditorOption[];
};

export const defaultAiProvider: Provider = ProviderSchema.parse({
	id: 'provider-new',
	name: 'provider-new',
	enabled: true,
});

const defaultApiTypeOptions = DefaultApiRegistry.apiTypes.map((apiType) => ({
	value: apiType.name,
	label: apiType.name,
	description: apiType.family.name,
}));

const defaultMessages: AiProviderEditorMessages = {
	title: 'AI Provider 配置',
	description: '编辑独立 Provider 身份、连接、路由能力和扩展配置。',
	sections: { identity: '身份', connection: '连接与凭据', routing: '路由与能力', metadata: '标签与扩展' },
	fields: {
		id: 'ID',
		name: '名称',
		title: '显示名称',
		description: '描述',
		type: 'Provider 类型',
		apiType: 'API 类型',
		baseUrl: 'Base URL',
		apiKey: 'API Key',
		headers: '请求头',
		env: '环境变量值',
		envVars: '环境变量引用',
		credentials: '凭据扩展',
		proxyMode: '代理模式',
		proxy: '启用代理',
		endpoints: 'Endpoint 引用',
		defaultEndpointId: '默认 Endpoint',
		defaultModelId: '默认 Model',
		capabilities: '能力',
		tags: '标签',
		labels: 'Labels',
		notes: '备注',
		options: 'Options',
		extensions: 'Extensions',
		enabled: '启用 Provider',
	},
};

export function AiProviderEditor({
	value,
	onChange,
	onSubmit,
	schema = ProviderSchema,
	validationMode,
	disabled = false,
	readOnly = false,
	messages: messageOverrides,
	slots,
	apiTypeOptions = defaultApiTypeOptions,
	...props
}: AiProviderEditorProps) {
	const messages = mergeResourceEditorMessages(defaultMessages, messageOverrides);
	const controller = useAiConfigDraft({
		value,
		fallbackValue: defaultAiProvider,
		schema,
		onChange,
		onSubmit,
		validationMode,
	});
	const draft = controller.draft;
	const patch = (next: Partial<Provider>) => controller.setDraft({ ...draft, ...next });
	const field = (name: AiProviderEditorField, defaultField: ReactNode) => (
		<AiConfigFieldSlot
			name={name}
			draft={draft}
			disabled={disabled}
			readOnly={readOnly}
			error={aiConfigFieldError(controller.visibleIssues, name)}
			defaultField={defaultField}
			onDraftChange={controller.setDraft}
			slots={slots}
		/>
	);
	const locked = disabled || readOnly;
	return (
		<AiConfigEditor
			{...props}
			title={messages.title}
			description={messages.description}
			controller={controller}
			messages={messages.editor}
			slots={slots}
			disabled={disabled}
			readOnly={readOnly}
			showSubmit={Boolean(onSubmit)}
		>
			<AiConfigFormSection title={messages.sections.identity}>
				<AiConfigFieldGrid>
					{field(
						'id',
						<AiConfigTextField
							label={messages.fields.id}
							required
							value={draft.id}
							error={aiConfigFieldError(controller.visibleIssues, 'id')}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(id) => patch({ id })}
						/>,
					)}
					{field(
						'name',
						<AiConfigTextField
							label={messages.fields.name}
							required
							value={draft.name}
							error={aiConfigFieldError(controller.visibleIssues, 'name')}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(name) => patch({ name })}
						/>,
					)}
					{field(
						'title',
						<AiConfigTextField
							label={messages.fields.title}
							value={draft.title}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(title) => patch({ title: optional(title) })}
						/>,
					)}
					{field(
						'type',
						<AiConfigTextField
							label={messages.fields.type}
							value={draft.type}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(type) => patch({ type: optional(type) })}
						/>,
					)}
				</AiConfigFieldGrid>
				{field(
					'description',
					<AiConfigTextareaField
						wrapperClassName='mt-4'
						label={messages.fields.description}
						value={draft.description}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(description) => patch({ description: optional(description) })}
					/>,
				)}
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.connection}>
				<AiConfigFieldGrid>
					{field(
						'apiType',
						<AiConfigSelectField
							label={messages.fields.apiType}
							value={draft.apiType}
							options={apiTypeOptions}
							disabled={locked}
							onValueChange={(apiType) => patch({ apiType: optional(apiType) })}
						/>,
					)}
					{field(
						'baseUrl',
						<AiConfigTextField
							type='url'
							label={messages.fields.baseUrl}
							value={draft.baseUrl}
							placeholder='https://api.example.com/v1'
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(baseUrl) => patch({ baseUrl: optional(baseUrl) })}
						/>,
					)}
				</AiConfigFieldGrid>
				{field(
					'apiKey',
					<AiConfigSecretField
						wrapperClassName='mt-4'
						label={messages.fields.apiKey}
						revealIdentity={value.id}
						value={draft.apiKey}
						placeholder='placeholder-secret'
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(apiKey) => patch({ apiKey: optional(apiKey) })}
					/>,
				)}
				<div className='mt-4 grid min-w-0 gap-4 lg:grid-cols-2'>
					{field(
						'headers',
						<AiConfigKeyValueField
							label={messages.fields.headers}
							value={draft.headers}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(headers) => patch({ headers })}
						/>,
					)}
					{field(
						'env',
						<AiConfigKeyValueField
							label={messages.fields.env}
							value={draft.env}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(env) => patch({ env })}
						/>,
					)}
				</div>
				{field(
					'envVars',
					<AiConfigStringListField
						className='mt-4'
						label={messages.fields.envVars}
						value={draft.envVars}
						disabled={disabled}
						readOnly={readOnly}
						onChange={(envVars) => patch({ envVars })}
					/>,
				)}
				{field(
					'credentials',
					<JsonValueEditor
						className='mt-4'
						label={messages.fields.credentials}
						value={draft.credentials ?? {}}
						disabled={disabled}
						readOnly={readOnly}
						onChange={(credentials) => patch({ credentials: credentials as Provider['credentials'] })}
					/>,
				)}
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.routing}>
				<AiConfigFieldGrid>
					{field(
						'proxyMode',
						<AiConfigSelectField
							label={messages.fields.proxyMode}
							value={draft.proxyMode}
							options={[
								{ value: 'direct', label: '直连' },
								{ value: 'proxy', label: '代理' },
							]}
							disabled={locked}
							onValueChange={(proxyMode) =>
								patch({ proxyMode: proxyMode ? (proxyMode as Provider['proxyMode']) : undefined })
							}
						/>,
					)}
					{field(
						'proxy',
						<AiConfigToggleField
							label={messages.fields.proxy}
							checked={draft.proxy ?? false}
							disabled={locked}
							onCheckedChange={(proxy) => patch({ proxy })}
						/>,
					)}
					{field(
						'defaultEndpointId',
						<AiConfigTextField
							label={messages.fields.defaultEndpointId}
							value={draft.defaultEndpointId}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(defaultEndpointId) => patch({ defaultEndpointId: optional(defaultEndpointId) })}
						/>,
					)}
					{field(
						'defaultModelId',
						<AiConfigTextField
							label={messages.fields.defaultModelId}
							value={draft.defaultModelId}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(defaultModelId) => patch({ defaultModelId: optional(defaultModelId) })}
						/>,
					)}
				</AiConfigFieldGrid>
				<div className='mt-4 grid min-w-0 gap-4 lg:grid-cols-2'>
					{field(
						'endpoints',
						<AiConfigStringListField
							label={messages.fields.endpoints}
							value={draft.endpoints}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(endpoints) => patch({ endpoints })}
						/>,
					)}
					{field(
						'capabilities',
						<AiConfigStringListField
							label={messages.fields.capabilities}
							value={draft.capabilities}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(capabilities) => patch({ capabilities })}
						/>,
					)}
				</div>
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.metadata}>
				<div className='grid min-w-0 gap-4 lg:grid-cols-2'>
					{field(
						'tags',
						<AiConfigStringListField
							label={messages.fields.tags}
							value={draft.tags}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(tags) => patch({ tags })}
						/>,
					)}
					{field(
						'labels',
						<AiConfigKeyValueField
							label={messages.fields.labels}
							value={draft.labels}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(labels) => patch({ labels })}
						/>,
					)}
				</div>
				{field(
					'notes',
					<AiConfigTextareaField
						wrapperClassName='mt-4'
						label={messages.fields.notes}
						value={draft.notes}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(notes) => patch({ notes: optional(notes) })}
					/>,
				)}
				<div className='mt-4 grid min-w-0 gap-4 lg:grid-cols-2'>
					{field(
						'options',
						<JsonValueEditor
							label={messages.fields.options}
							value={draft.options ?? {}}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(options) => patch({ options: options as Provider['options'] })}
						/>,
					)}
					{field(
						'extensions',
						<JsonValueEditor
							label={messages.fields.extensions}
							value={draft.extensions ?? {}}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(extensions) => patch({ extensions: extensions as Provider['extensions'] })}
						/>,
					)}
				</div>
				{field(
					'enabled',
					<AiConfigToggleField
						wrapperClassName='mt-4'
						label={messages.fields.enabled}
						checked={draft.enabled ?? true}
						disabled={locked}
						onCheckedChange={(enabled) => patch({ enabled })}
					/>,
				)}
			</AiConfigFormSection>
		</AiConfigEditor>
	);
}

function optional(value: string): string | undefined {
	return value.trim() ? value : undefined;
}
